import pandas as pd,numpy as np
from scipy.signal import lfilter
files=['train/A2_vref_op1.csv','train/A2_vref_op3.csv','train/A2_amb_op1.csv','train/A2_amb_op2.csv','train/A2_load_op2.csv']
Ds=[pd.read_csv(f) for f in files]
def basis(d,taus,sig):
    t=d.time_s.values; dt=t[1]-t[0]
    V=d.voltage_pu.values; S=d.voltage_setpoint_pu.values
    cols=[np.ones_like(V)]
    for tau in taus:
        a=np.exp(-dt/tau)
        cols.append(lfilter([1-a],[1,-a],V-V[0])); 
        if sig: cols.append(lfilter([1-a],[1,-a],S-S[0]))
    return np.column_stack(cols)
for taus in [[0.1,1],[0.05,0.5],[0.02,0.1,0.5,2],[0.05,0.3,2],[0.1,0.5,3]]:
  for sig in [1]:
    rs=[]
    Xs=[];Ys=[]
    for d in Ds:
        X=basis(d,taus,sig); Y=d.reactive_power_pu.values-d.reactive_power_pu.values[0]
        Xs.append(X);Ys.append(Y)
    c,*_=np.linalg.lstsq(np.vstack(Xs),np.concatenate(Ys),rcond=None)
    r=[np.sqrt(np.mean((Y-X@c)**2)).round(5) for X,Y in zip(Xs,Ys)]
    print(taus,r,np.round(c,3))
